  function oceanPalette() {
    const rgb = (hex) => hex.match(/[a-f0-9]{2}/gi).map((value) => parseInt(value, 16));
    let mode = settings.oceanColorMode;
    if (mode === 'original') return [null, '#e0892c', [230, 238, 255], [110, 230, 255]];
    if (mode === 'auto')
      mode = document.documentElement.getAttribute('data-cgfc-theme') === 'light' ? 'warm' : 'cyan';
    const presets = {
      cyan: ['#7ed8f0', '#c79aff', '#b8e7f7', '#55d8ea'],
      aurora: ['#b9a5ff', '#8af2c9', '#d3c2ff', '#bb81fa'],
      warm: ['#dba15b', '#e58465', '#f5dcb7', '#e8bb69'],
    };
    let colors = presets[mode];
    if (mode === 'custom')
      colors = [
        settings.oceanBodyColor,
        settings.oceanAccentColor,
        settings.oceanFishColor,
        settings.oceanWakeColor,
      ];
    if (mode === 'random') {
      let seed = settings.oceanColorSeed | 0;
      const random = () => {
        seed ^= seed << 13;
        seed ^= seed >>> 17;
        seed ^= seed << 5;
        return (seed >>> 0) / 4294967296;
      };
      const hue = random();
      const hsl = (h, s, l) => {
        const f = (n) => {
          const k = (n + h * 12) % 12;
          return Math.round(
            255 * (l - s * Math.min(l, 1 - l) * Math.max(-1, Math.min(k - 3, 9 - k, 1))),
          );
        };
        return (
          '#' + [f(0), f(8), f(4)].map((value) => value.toString(16).padStart(2, '0')).join('')
        );
      };
      colors = [
        hsl(hue, 0.65, 0.67),
        hsl((hue + 0.18) % 1, 0.7, 0.7),
        hsl(hue, 0.5, 0.82),
        hsl((hue + 0.06) % 1, 0.8, 0.62),
      ];
    }
    colors ??= presets.cyan;
    return [rgb(colors[0]), colors[1], rgb(colors[2]), rgb(colors[3])];
  }

