  function normalizeSettings(input) {
    const result = { ...DEFAULTS };
    if (!input || typeof input !== 'object' || Array.isArray(input)) return result;
    for (const [key, spec] of Object.entries(SCHEMA)) {
      if (own(input, key)) {
        const value = input[key];
        if (spec.type === 'boolean')
          result[key] = typeof value === 'boolean' ? value : spec.default;
        else if (spec.type === 'number') {
          const n = Number(value);
          result[key] = Number.isFinite(n) ? clamp(n, spec.min, spec.max) : spec.default;
        } else if (spec.type === 'select')
          result[key] = spec.choices.includes(value) ? value : spec.default;
        else if (spec.type === 'color') result[key] = color(value, spec.default);
        else if (spec.type === 'url') result[key] = imageURL(value);
        else result[key] = cssFont(value, spec.default);
      }
      if (spec.override && typeof input[key + 'Enabled'] === 'boolean')
        result[key + 'Enabled'] = input[key + 'Enabled'];
    }
    return result;
  }
